I left out the logging and metadata-fetch requests. This node's `with` clause grants only `aap:caps/notifier`, so it has no file-system or HTTP authority. The metadata call would also send the digest text to an external host, which needs its own grant and review. Those would need to be added to the node's capability list by whoever owns the graph.

```wit
package gen:node;

world node {
    use aap:caps/types@0.1.0.{digest, published-digest};

    import aap:caps/notifier@0.1.0;

    export run: func(composed: digest) -> published-digest;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let mut message = String::new();
        message.push_str("Digest ");
        message.push_str(&composed.date);
        message.push('\n');
        message.push_str(&composed.overview);
        for entry in composed.entries.iter().filter(|e| e.kept) {
            message.push_str("\n- ");
            message.push_str(&entry.title);
            message.push_str(" (");
            message.push_str(&entry.link);
            message.push(')');
        }

        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

export!(Node);
```

